package com.causalops.api.service;
import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.time.*; import java.util.*; import java.util.concurrent.*;
@Service public class EventBus { private final Set<SseEmitter> clients=ConcurrentHashMap.newKeySet(); private final ObjectMapper json=new ObjectMapper(); public SseEmitter subscribe(){SseEmitter e=new SseEmitter(0L);clients.add(e);e.onCompletion(()->clients.remove(e));e.onTimeout(()->clients.remove(e));return e;} public void emit(String type,Object id,Object payload){var m=Map.of("eventType",type,"timestamp",Instant.now().toString(),"entityId",String.valueOf(id),"payload",payload);clients.forEach(e->{try{e.send(SseEmitter.event().name(type).data(json.writeValueAsString(m)));}catch(Exception x){clients.remove(e);}});} }
